# ─── Token türleri ───────────────────────────────────────────────
class Token:
    __slots__ = ("kind", "value")

    def __init__(self, kind: str, value=None):
        self.kind = kind
        self.value = value

    def __repr__(self):
        return f"Token({self.kind}, {self.value!r})"


# ─── Tokenizer ───────────────────────────────────────────────────
class Tokenizer:
    KEYWORDS = ("min", "max", "abs")

    def __init__(self, code: str):
        self.code = code
        self.pos = 0
        self._tokens = self._tokenize()

    def _tokenize(self):
        toks = []
        i = 0
        n = len(self.code)
        while i < n:
            ch = self.code[i]

            # boşluk
            if ch in " \t\r":
                i += 1

            # yorum
            elif ch == "#":
                while i < n and self.code[i] != "\n":
                    i += 1

            # sayı
            elif ch.isdigit() or (ch == "." and i + 1 < n and self.code[i + 1].isdigit()):
                start = i
                has_dot = False
                i += 1
                while i < n:
                    c = self.code[i]
                    if c == ".":
                        if has_dot:
                            raise SyntaxError(f"Sayı okunamadı: '{self.code[start:i+1]}'")
                        has_dot = True
                    elif c.isdigit():
                        pass
                    else:
                        break
                    i += 1
                toks.append(Token("NUM", self.code[start:i]))

            # parantez / işleç
            elif ch == "(" or ch == ")":
                toks.append(Token(ch))
                i += 1

            # işaretsiz atama işareti
            elif ch == "=":
                toks.append(Token("ASSIGN"))
                i += 1

            # yeni satır / ifade ayırıcı
            elif ch == ";":
                toks.append(Token("END"))
                i += 1

            # + - * / % **
            elif ch == "*":
                if i + 1 < n and self.code[i + 1] == "*":
                    toks.append(Token("POW"))
                    i += 2
                else:
                    toks.append(Token(ch))
                    i += 1
            elif ch == "+":
                toks.append(Token(ch))
                i += 1
            elif ch == "-":
                toks.append(Token(ch))
                i += 1
            elif ch == "/":
                toks.append(Token(ch))
                i += 1
            elif ch == "%":
                toks.append(Token(ch))
                i += 1

            # tanınmayan karakter
            else:
                raise SyntaxError(f"Beklenmeyen karakter: '{ch}'")

        toks.append(Token("EOF"))
        return toks

    def cur(self):
        return self._tokens[self.pos]

    def advance(self):
        tok = self.cur()
        if self.pos < len(self._tokens) - 1:
            self.pos += 1
        return tok


# ─── Parser ──────────────────────────────────────────────────────
class Parser:
    """Recursive descent parser.
    Öncelik (düşük → yüksek):
      assignment
      expr:   add / sub
      term:   mul / div / mod
      factor: unary / power
      power:  atom [** power]  (sağdan birleşen)
    """

    def __init__(self, tokens):
        self.tokens = tokens

    # yardımcı: mevcut tokeni beklenenle karşılaştır, ilerlet
    def expect(self, kind):
        tok = self.tokens.cur()
        if tok.kind != kind:
            raise SyntaxError(f"Beklenen '{kind}', bulundu '{tok.kind}'")
        return self.tokens.advance()

    # ── expression (add / sub) ─────────────────────────────────
    def parse_expr(self, env):
        left = self.parse_term(env)
        while self.tokens.cur().kind in ("+", "-"):
            op = self.tokens.advance()
            right = self.parse_term(env)
            if op.kind == "+":
                left = left + right
            else:
                left = left - right
        return left

    # ── term (mul / div / mod) ─────────────────────────────────
    def parse_term(self, env):
        left = self.parse_power(env)
        while self.tokens.cur().kind in ("*", "/", "%"):
            op = self.tokens.advance()
            right = self.parse_power(env)
            if op.kind == "*":
                left = left * right
            elif op.kind == "/":
                if isinstance(right, int) and right == 0:
                    raise ZeroDivisionError("Sıfıra bölme")
                left = left / right
            else:
                if isinstance(right, int) and right == 0:
                    raise ZeroDivisionError("Sıfıra bölme")
                left = left % right
        return left

    # ── power (unary / **) ──────────────────────────────────────
    #  ** sağdan birleşir: 2 ** -1 ** 2 → 2 ** (-1 ** 2) = 2 ** -1 = 0.5
    def parse_power(self, env):
        if self.tokens.cur().kind in ("+", "-"):
            op = self.tokens.advance()
            operand = self.parse_power(env)
            if op.kind == "-":
                operand = -operand
            return operand

        base = self.parse_atom(env)

        # ** sağdan birleşir, recursive call
        if self.tokens.cur().kind == "**":
            self.tokens.advance()
            exp = self.parse_power(env)
            base = base ** exp

        return base

    # ── atom (sayı / parantez / fonksiyon / ad) ─────────────────
    def parse_atom(self, env):
        tok = self.tokens.cur()

        # sayı
        if tok.kind == "NUM":
            self.tokens.advance()
            s = tok.value
            if "." in s:
                return float(s)
            else:
                return int(s)

        # parantezli ifade
        if tok.kind == "(":
            self.tokens.advance()
            val = self.parse_expr(env)
            self.expect(")")
